SELECT jsonb_build_object(
'unsupported',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'persistence',c.relpersistence,'replica_identity',c.relreplident,'tablespace',c.reltablespace)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','homework_api') AND (c.relkind NOT IN ('r','S','i','I') OR c.relpersistence<>'p' OR c.relreplident<>'d' OR c.reltablespace<>0)),
'column_metadata',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END,'stats',a.attstattarget,'storage',a.attstorage,'compression',a.attcompression)) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','homework_api') AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped),
'comments',(SELECT jsonb_agg(jsonb_build_object('object',d.objoid::text,'subid',d.objsubid,'class',d.classoid::regclass::text,'comment',d.description)) FROM pg_description d WHERE (d.classoid='pg_class'::regclass AND d.objoid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','homework_api'))) OR (d.classoid='pg_proc'::regclass AND d.objoid IN (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','homework_api'))) OR (d.classoid='pg_namespace'::regclass AND d.objoid IN (SELECT oid FROM pg_namespace WHERE nspname IN ('public','homework_api')))),
'rules',(SELECT count(*) FROM pg_rewrite w JOIN pg_class c ON c.oid=w.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','homework_api')),
'other_types',(SELECT jsonb_agg(jsonb_build_object('name',t.typname,'kind',t.typtype)) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('public','homework_api') AND t.typtype NOT IN ('c') AND t.typelem=0),
'column_grants',(SELECT count(*) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','homework_api') AND a.attacl IS NOT NULL),
'publications',(SELECT jsonb_agg(to_jsonb(t)) FROM pg_publication_tables t WHERE schemaname IN ('public','homework_api')),
'collations',(SELECT count(*) FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace WHERE n.nspname IN ('public','homework_api')),
'extended_statistics',(SELECT count(*) FROM pg_statistic_ext s JOIN pg_namespace n ON n.oid=s.stxnamespace WHERE n.nspname IN ('public','homework_api')),
'foreign_grantors',(SELECT jsonb_agg(DISTINCT pg_get_userbyid(a.grantor)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE n.nspname IN ('public','homework_api') AND a.grantor<>c.relowner)
) AS snapshot;
